#!/usr/bin/env python3
"""Brico68k Compiler - builds the Brico68k firmware (Neo Geo diagnostic ROM for
the BricoNeo board / Brico16Bits host firmware) with a simple interface.

- Source: a folder (by default this script's folder, or its "source/" sub-folder,
  when it contains Brico68k.s), a .zip archive, or Aurelien34/Brico68k on GitHub
  (latest release or main, downloaded automatically).
- vasm / vlink: FULLY AUTOMATIC. Windows x64 and Linux x64: vasm 1.9d and
  vlink 0.17a are embedded in this file (extracted on first use, no download).
  Other systems (macOS...): downloaded and built from source automatically
  (gcc/clang, or the zig compiler installed through pip). Your own executables
  can also be used.
- Result: ROM.BIO, ready to copy to the BricoNeo USB drive, with a
  Brico16Bits compatibility check (header, byte order, extension table, size).
- At start-up, missing files (source files, includes, embedded tools, output
  folder) are listed in a red box instead of failing later during the build.

Everything the tool downloads or builds stays in the "brico68k_compiler"
sub-folder next to this script.

Run: double-click, or  python Brico68k_Compiler.py
Text mode (no window): python Brico68k_Compiler.py --cli [--source FOLDER|ZIP|github[:tag]] [--out FOLDER]
Check only:            python Brico68k_Compiler.py --check [--source FOLDER]
Python 3.8+; standard library only (tkinter for the window).
"""
import base64
import hashlib
import json
import lzma
import platform
import os
import queue
import re
import shutil
import struct
import subprocess
import sys
import tarfile
import tempfile
import threading
import time
import zipfile
from pathlib import Path

APP_NAME = "Brico68k Compiler"
APP_VERSION = "1.6"

TOOL_DIR = Path(__file__).resolve().parent
WORK_DIR = TOOL_DIR / "brico68k_compiler"
TOOLCHAIN_DIR = WORK_DIR / "toolchain"
BIN_DIR = TOOLCHAIN_DIR / "bin"
SRC_DIR = TOOLCHAIN_DIR / "src"
ZIG_DIR = TOOLCHAIN_DIR / "ziglang"
BUILD_DIR = WORK_DIR / "build"
CONFIG_PATH = WORK_DIR / "config.json"
DEFAULT_OUT = TOOL_DIR / "output"

IS_WIN = os.name == "nt"
EXE = ".exe" if IS_WIN else ""
NO_WINDOW = 0x08000000 if IS_WIN else 0  # no flashing console window on Windows

VASM_NAMES = ["vasmm68k_mot", "vasmm68k_mot_win64", "vasmm68k_mot_win32"]
VLINK_NAMES = ["vlink"]

# vasm/vlink sources, tried in order (Leffmann/* = GitHub mirrors of the
# official sources by Volker Barthelmann / Frank Wille).
TOOL_SOURCES = {
    "vasm": [
        ("zip", "https://github.com/Leffmann/vasm/archive/refs/heads/master.zip"),
        ("git", "https://github.com/Leffmann/vasm.git"),
        ("tgz", "http://sun.hasenbraten.de/vasm/release/vasm.tar.gz"),
    ],
    "vlink": [
        ("zip", "https://github.com/Leffmann/vlink/archive/refs/heads/master.zip"),
        ("git", "https://github.com/Leffmann/vlink.git"),
        ("tgz", "http://sun.hasenbraten.de/vlink/release/vlink.tar.gz"),
    ],
}

# Firmware source on GitHub (original repository, read-only)
GITHUB_REPO = "https://github.com/Aurelien34/Brico68k"
GITHUB_DEFAULT_BRANCH = "main"

# Same options as build.py in the Brico68k repository
ASM_FLAGS = ["-chklabels", "-nocase", "-Fvobj", "-m68000", "-Dvasm=1", "-DBuildNEO=1", "-spaces", "-quiet"]
TARGET_NAME = "Brico68k"
ROM_FILE = "ROM.BIO"        # name of the built ROM (BricoNeo drive: .BIN, .BIO or .ROM)

# Format expected by Brico16Bits (MemoryMap.h / BricoExtManager.cpp / ROMImageManager.cpp)
SP1_SIZE = 128 * 1024
OFF_MAGIC, OFF_VERSION, OFF_FLAGS, OFF_JMP, OFF_TABLE = 0x80, 0x88, 0x8C, 0x8E, 0xA0
FLAG_ENABLE_EXTENSIONS = 0x0001
HOST_NAME_MAX, HOST_DESC_MAX = 15, 300  # Brico16Bits Commands/Command.h


class BuildError(Exception):
    pass


def _run(cmd, cwd=None, env=None, log=None, timeout=900):
    p = subprocess.run(cmd, cwd=cwd, env=env, capture_output=True, timeout=timeout,
                       creationflags=NO_WINDOW)
    out = (p.stdout or b"").decode("utf-8", "replace") + (p.stderr or b"").decode("utf-8", "replace")
    if log and out.strip():
        for line in out.strip().splitlines()[-40:]:
            log(line)
    return p.returncode, out


# ---------------------------------------------------------------------------
# Settings
# ---------------------------------------------------------------------------
def load_config():
    try:
        return json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
    except Exception:
        return {}


def save_config(cfg):
    try:
        WORK_DIR.mkdir(parents=True, exist_ok=True)
        CONFIG_PATH.write_text(json.dumps(cfg, indent=2), encoding="utf-8")
    except Exception:
        pass


# ---------------------------------------------------------------------------
# Firmware source
# ---------------------------------------------------------------------------
def find_source_root(path):
    """Folder containing Brico68k.s (directly or one level below)."""
    path = Path(path)
    if (path / f"{TARGET_NAME}.s").is_file():
        return path
    for sub in sorted(path.iterdir()) if path.is_dir() else []:
        if sub.is_dir() and (sub / f"{TARGET_NAME}.s").is_file():
            return sub
    raise BuildError(f"Brico68k.s not found in {path}: this is not the Brico68k firmware source.")


def describe_source(root):
    root = Path(root)
    n = len(list(root.glob("*.s")))
    ver = ""
    try:
        m = re.search(r"BRICONEO_VERSION\s+(\d+)\s*,\s*(\d+)", (root / f"{TARGET_NAME}.s").read_text(errors="replace"))
        if m:
            ver = f", version {m.group(1)}.{m.group(2)}"
    except Exception:
        pass
    return f"{n} .s files{ver}"


def default_source_dir():
    try:
        return str(find_source_root(TOOL_DIR))
    except BuildError:
        return ""


# ---------------------------------------------------------------------------
# Start-up check: what is missing?
# ---------------------------------------------------------------------------
_INCLUDE_RE = re.compile(r'^\s*include\s+"([^"]+)"', re.I | re.M)


def check_source_files(root):
    """Missing files in a source folder: [(what, path)]. Empty list = complete."""
    missing = []
    root = Path(root)
    for name, what in ((f"{TARGET_NAME}.s", "main source file"),
                       (f"{TARGET_NAME}.ld", "linker script"),
                       ("inc/define.inc", "shared definitions")):
        if not (root / name).is_file():
            missing.append((what, str(root / name)))
    seen = set()
    for s in sorted(root.glob("*.s")):
        try:
            text = s.read_text(errors="replace")
        except OSError as e:
            missing.append((f"unreadable source file ({e})", str(s)))
            continue
        for inc in _INCLUDE_RE.findall(text):
            p = root / inc
            if inc not in seen and not p.is_file():
                missing.append((f"include used by {s.name}", str(p)))
            seen.add(inc)
    return missing


def embedded_tools_status():
    """(platform, problem or None). Checks the embedded vasm/vlink data without extracting."""
    plat = embedded_platform()
    tools = globals().get("EMBEDDED_TOOLS", {}).get(plat) if plat else None
    if not tools:
        return plat, None  # not embedded for this system: built from source on first build
    for name, (sha, data) in tools.items():
        dest = BIN_DIR / name
        try:
            if dest.is_file() and hashlib.sha256(dest.read_bytes()).hexdigest() == sha:
                continue
            raw = lzma.decompress(base64.b64decode(data))
            if hashlib.sha256(raw).hexdigest() != sha:
                return plat, f"embedded {name} is corrupted (checksum)"
        except Exception as e:
            return plat, f"embedded {name} unreadable ({e})"
    return plat, None


def startup_check(source_mode="folder", source_path="", out_dir=None, manual=None):
    """Everything the next build needs. Returns [(what, detail)] of missing items."""
    missing = []
    if sys.version_info < (3, 8):
        missing.append(("Python 3.8 or newer", f"running {sys.version.split()[0]}"))
    if source_mode == "folder":
        if not source_path:
            missing.append(("firmware source folder", "not selected (must contain Brico68k.s)"))
        else:
            try:
                missing += check_source_files(find_source_root(source_path))
            except BuildError:
                missing.append(("Brico68k.s (firmware source)", str(Path(source_path) / "Brico68k.s")))
    elif source_mode == "zip":
        if not source_path or not Path(source_path).is_file():
            missing.append(("source .zip archive", source_path or "not selected"))
    if manual and all(manual):
        for p, what in zip(manual, ("vasm executable", "vlink executable")):
            if not Path(p).is_file():
                missing.append((what, p))
    else:
        plat, problem = embedded_tools_status()
        if problem:
            missing.append(("vasm/vlink embedded in this file", problem + " - download the tool again"))
    if out_dir:
        out = Path(out_dir)
        probe = out if out.is_dir() else out.parent
        if not probe.is_dir() or not os.access(probe, os.W_OK):
            missing.append(("writable output folder", str(out)))
    return missing


# ---------------------------------------------------------------------------
# vasm / vlink
# ---------------------------------------------------------------------------
def _which(names):
    for n in names:
        p = shutil.which(n) or shutil.which(n + ".exe")
        if p:
            return p
    return None


def cached_tools():
    v, l = BIN_DIR / f"vasmm68k_mot{EXE}", BIN_DIR / f"vlink{EXE}"
    return (str(v) if v.is_file() else None), (str(l) if l.is_file() else None)


def locate_tools():
    """PATH, then the tool's local cache."""
    cv, cl = cached_tools()
    return (_which(VASM_NAMES) or cv), (_which(VLINK_NAMES) or cl)


_PROBED = set()                 # (path, size, mtime) of vasm/vlink pairs that passed probe_tools


def probe_tools(vasm, vlink, log=None):
    """Checks that vasm and vlink really work (assemble + link 1 word). A pair that passed is not
    tested again while this program runs and the two files are unchanged (1.5)."""
    if not vasm or not Path(vasm).is_file():
        return False, f"vasm not found: {vasm}"
    if not vlink or not Path(vlink).is_file():
        return False, f"vlink not found: {vlink}"
    key = tuple((str(Path(x).resolve()), Path(x).stat().st_size, Path(x).stat().st_mtime_ns) for x in (vasm, vlink))
    if key in _PROBED:
        return True, "vasm and vlink work"
    ok, msg = _probe_tools(vasm, vlink)
    if ok:
        _PROBED.add(key)
    return ok, msg


def _probe_tools(vasm, vlink):
    with tempfile.TemporaryDirectory(prefix="b68kprobe_") as t:
        t = Path(t)
        (t / "p.s").write_text("\tsection text,code\n\tdc.w $1234\n")
        try:
            rc, out = _run([vasm, "-Fvobj", "-m68000", "-quiet", "-o", str(t / "p.o"), str(t / "p.s")], timeout=60)
            if rc != 0:
                return False, f"vasm does not work ({vasm}): {out.strip()[:300]}"
            rc, out = _run([vlink, "-brawbin1", "-o", str(t / "p.bin"), str(t / "p.o")], timeout=60)
            if rc != 0:
                return False, f"vlink does not work ({vlink}): {out.strip()[:300]}"
        except OSError as e:
            return False, f"cannot start the tool: {e}"
        data = (t / "p.bin").read_bytes() if (t / "p.bin").exists() else b""
        if data != b"\x12\x34":
            return False, f"unexpected test result ({data.hex()}) - wrong vasm/vlink?"
    return True, "vasm and vlink work"


def _c_compiler(log):
    """C compiler command: the system one if present, otherwise zig (pip)."""
    for name in (["gcc", "clang", "cc"] if not IS_WIN else ["gcc", "clang"]):
        p = shutil.which(name)
        if p:
            log(f"C compiler found: {p}")
            return [p], dict(os.environ)
    env = dict(os.environ)
    env["PYTHONPATH"] = str(ZIG_DIR) + (os.pathsep + env["PYTHONPATH"] if env.get("PYTHONPATH") else "")
    env["ZIG_GLOBAL_CACHE_DIR"] = str(TOOLCHAIN_DIR / "zig-cache")
    env["ZIG_LOCAL_CACHE_DIR"] = str(TOOLCHAIN_DIR / "zig-cache")
    if not (ZIG_DIR / "ziglang").is_dir():
        log("No C compiler on this machine: installing the zig compiler (pip package 'ziglang',")
        log(f"  into {ZIG_DIR}, nothing is installed elsewhere). About 100 MB, downloaded once...")
        ZIG_DIR.mkdir(parents=True, exist_ok=True)
        rc, out = _run([sys.executable, "-m", "pip", "install", "--disable-pip-version-check",
                        "--no-warn-script-location", "--upgrade", "--target", str(ZIG_DIR), "ziglang"],
                       log=log, timeout=1800)
        if rc != 0 or not (ZIG_DIR / "ziglang").is_dir():
            raise BuildError("Could not install 'ziglang' with pip (no internet, or pip missing). "
                             "Set your own vasm/vlink paths (untick 'Automatic').")
    rc, out = _run([sys.executable, "-m", "ziglang", "version"], env=env, timeout=120)
    if rc != 0:
        raise BuildError(f"The zig compiler does not start: {out.strip()[:300]}")
    log(f"C compiler: zig {out.strip()} (pip package ziglang)")
    return [sys.executable, "-m", "ziglang", "cc"], env


def _download(url, dest, log, progress):
    import urllib.request        # only when downloading: 40 ms less at start-up
    req = urllib.request.Request(url, headers={"User-Agent": f"{APP_NAME}/{APP_VERSION}"})
    with urllib.request.urlopen(req, timeout=60) as r, open(dest, "wb") as f:
        total = int(r.headers.get("Content-Length") or 0)
        got = 0
        while True:
            chunk = r.read(65536)
            if not chunk:
                break
            f.write(chunk)
            got += len(chunk)
            if progress and total:
                progress(got * 100 // total, f"Downloading {Path(url).name} ({got // 1024} KB)")


def _fetch_tool_source(name, marker, log, progress):
    """Gets the vasm or vlink sources into SRC_DIR/name."""
    dest = SRC_DIR / name
    if (dest / marker).is_file():
        log(f"{name} sources already present ({dest}).")
        return dest
    SRC_DIR.mkdir(parents=True, exist_ok=True)
    errors = []
    for kind, url in TOOL_SOURCES[name]:
        shutil.rmtree(dest, ignore_errors=True)
        tmp = SRC_DIR / f"_{name}_tmp"
        shutil.rmtree(tmp, ignore_errors=True)
        tmp.mkdir(parents=True)
        try:
            log(f"Getting {name} sources: {url}")
            if kind == "git":
                if not shutil.which("git"):
                    raise BuildError("git not installed")
                rc, out = _run(["git", "clone", "--depth", "1", url, str(tmp / name)], timeout=600)
                if rc != 0:
                    raise BuildError(out.strip()[:200])
            else:
                arch = tmp / ("src.zip" if kind == "zip" else "src.tgz")
                _download(url, arch, log, progress)
                if kind == "zip":
                    with zipfile.ZipFile(arch) as z:
                        z.extractall(tmp)
                else:
                    with tarfile.open(arch) as t:
                        if hasattr(tarfile, "data_filter"):     # Python 3.12+ (and 3.8-3.11 security releases)
                            t.extractall(tmp, filter="data")    # no absolute path, no "..", no link out of tmp
                        else:
                            root = str(tmp.resolve())
                            for m in t.getmembers():       # Python 3.8: no Path.is_relative_to
                                p = str((tmp / m.name).resolve())
                                if not (m.isfile() or m.isdir()) or os.path.commonpath([root, p]) != root:
                                    raise BuildError(f"unsafe entry in the archive: {m.name}")
                            t.extractall(tmp)
                arch.unlink()
            found = [p.parent for p in tmp.rglob(marker)]
            if not found:
                raise BuildError(f"{marker} missing from the archive")
            shutil.move(str(found[0]), str(dest))
            shutil.rmtree(tmp, ignore_errors=True)
            return dest
        except Exception as e:  # try the next source
            errors.append(f"{kind} {url}: {e}")
            log(f"  failed ({e}), trying the next source...")
            shutil.rmtree(tmp, ignore_errors=True)
    raise BuildError(f"Could not get the {name} sources:\n  " + "\n  ".join(errors))


def _vasm_sources(root):
    rules = (root / "make.rules").read_text(errors="replace")
    block = re.search(r"^OBJS\s*=(.*?)(?:\n\s*\n)", rules, re.S | re.M).group(1)
    out = []
    for n in re.findall(r"\$\(PRE\)(\w+)\.o", block):
        out.append(root / ("cpus/m68k/cpu.c" if n == "cpu" else "syntax/mot/syntax.c" if n == "syntax" else f"{n}.c"))
    return out


def _vlink_sources(root):
    rules = (root / "make.rules").read_text(errors="replace")
    block = re.search(r"^vlinkobjects\s*=(.*?)(?:\n\s*\n)", rules, re.S | re.M).group(1)
    return [root / f"{n}.c" for n in re.findall(r"\$\(DIR\)/(\w+)\.o", block) + ["version"]]


def install_toolchain(log, progress):
    """Downloads and builds vasm (m68k, mot syntax) and vlink into BIN_DIR."""
    BIN_DIR.mkdir(parents=True, exist_ok=True)
    progress(None, "Looking for a C compiler...")
    cc, env = _c_compiler(log)
    common = ["-O2", "-std=c99", "-w", "-Wno-error=implicit-function-declaration",
              "-Wno-error=implicit-int", "-Wno-error=int-conversion"]
    libm = [] if IS_WIN else ["-lm"]

    progress(None, "vasm sources...")
    vroot = _fetch_tool_source("vasm", "make.rules", log, progress)
    if not (vroot / "cpus/m68k/cpu.c").is_file():
        raise BuildError("Incomplete vasm sources (cpus/m68k/cpu.c missing).")
    outfmts = ["-DOUTAOUT", "-DOUTBIN", "-DOUTELF", "-DOUTGST", "-DOUTHUNK", "-DOUTIHEX",
               "-DOUTO65", "-DOUTSREC", "-DOUTTOS", "-DOUTVOBJ", "-DOUTXFIL"]
    vasm_out = BIN_DIR / f"vasmm68k_mot{EXE}"
    progress(None, "Building vasm (1 to 3 minutes)...")
    log("Building vasm...")
    rc, out = _run(cc + common + ([] if IS_WIN else ["-DUNIX"]) + outfmts +
                   ["-I", str(vroot), "-I", str(vroot / "cpus/m68k"), "-I", str(vroot / "syntax/mot")] +
                   [str(s) for s in _vasm_sources(vroot)] + ["-o", str(vasm_out)] + libm,
                   cwd=str(vroot), env=env, log=log, timeout=1800)
    if rc != 0 or not vasm_out.is_file():
        raise BuildError("Building vasm failed (see the log).")

    progress(None, "vlink sources...")
    lroot = _fetch_tool_source("vlink", "vlink.h", log, progress)
    vlink_out = BIN_DIR / f"vlink{EXE}"
    progress(None, "Building vlink (1 to 3 minutes)...")
    log("Building vlink...")
    rc, out = _run(cc + common + ["-I", str(lroot)] + [str(s) for s in _vlink_sources(lroot)] +
                   ["-o", str(vlink_out)] + libm, cwd=str(lroot), env=env, log=log, timeout=1800)
    if rc != 0 or not vlink_out.is_file():
        raise BuildError("Building vlink failed (see the log).")

    ok, msg = probe_tools(str(vasm_out), str(vlink_out))
    if not ok:
        raise BuildError(f"vasm/vlink built but the self-test fails: {msg}")
    log(f"vasm and vlink installed in {BIN_DIR}")
    return str(vasm_out), str(vlink_out)


def embedded_platform():
    """Platform whose binaries are embedded in this file, or None."""
    m = platform.machine().lower()
    if IS_WIN and m in ("amd64", "x86_64", "arm64"):  # Windows 11 ARM runs x64 code
        return "windows-x86_64"
    if sys.platform.startswith("linux") and m in ("x86_64", "amd64"):
        return "linux-x86_64"
    return None


def extract_embedded(log=None):
    """Extracts (if needed) the embedded vasm/vlink into BIN_DIR. (vasm, vlink) or (None, None)."""
    plat = embedded_platform()
    tools = globals().get("EMBEDDED_TOOLS", {}).get(plat) if plat else None
    if not tools:
        return None, None
    BIN_DIR.mkdir(parents=True, exist_ok=True)
    paths = {}
    for name, (sha, data) in tools.items():
        dest = BIN_DIR / name
        if not (dest.is_file() and hashlib.sha256(dest.read_bytes()).hexdigest() == sha):
            raw = lzma.decompress(base64.b64decode(data))
            if hashlib.sha256(raw).hexdigest() != sha:
                raise BuildError(f"Embedded {name} is corrupted (checksum): download the tool again.")
            tmp = dest.with_name(dest.name + ".tmp")
            tmp.write_bytes(raw)
            os.chmod(tmp, 0o755)
            os.replace(tmp, dest)
            if log:
                log(f"{name} extracted from the tool to {dest}")
        paths[name] = str(dest)
    return paths.get(f"vasmm68k_mot{EXE}"), paths.get(f"vlink{EXE}")


def resolve_tools(auto, manual_vasm, manual_vlink, log, progress):
    if not auto:
        ok, msg = probe_tools(manual_vasm, manual_vlink)
        if not ok:
            raise BuildError(f"Manually set vasm/vlink paths: {msg}")
        return manual_vasm, manual_vlink
    if manual_vasm and manual_vlink:
        ok, _ = probe_tools(manual_vasm, manual_vlink)
        if ok:
            return manual_vasm, manual_vlink
    # 1. embedded binaries (Windows x64 / Linux x64): nothing to download
    try:
        v, l = extract_embedded(log)
    except Exception as e:  # disk full, antivirus...: go to plan B
        log(f"Embedded binaries unusable ({e}): plan B.")
        v = l = None
    if v and l:
        ok, msg = probe_tools(v, l)
        if ok:
            return v, l
        log(f"Embedded binaries rejected ({msg}) - antivirus? Plan B: sources.")
    # 2. PATH / cache, 3. download + build from source
    v, l = locate_tools()
    if v and l:
        ok, msg = probe_tools(v, l)
        if ok:
            return v, l
        log(f"vasm/vlink found but unusable ({msg}): reinstalling.")
    return install_toolchain(log, progress)


# ---------------------------------------------------------------------------
# Firmware build
# ---------------------------------------------------------------------------
def build_firmware(src_root, vasm, vlink, log, progress):
    src_root = Path(src_root)
    missing = check_source_files(src_root)
    if missing:
        raise BuildError("Missing files in the source:\n  " + "\n  ".join(f"{w}: {p}" for w, p in missing))
    shutil.rmtree(BUILD_DIR, ignore_errors=True)
    obj_dir, lst_dir = BUILD_DIR / "obj", BUILD_DIR / "listing"
    obj_dir.mkdir(parents=True)
    lst_dir.mkdir(parents=True)
    sources = sorted(src_root.glob("*.s"))
    ld = src_root / f"{TARGET_NAME}.ld"
    flags = ASM_FLAGS + [f"-I{src_root / 'inc'}"]
    objs = [str(obj_dir / f"{src.stem}.o") for src in sources]
    steps = len(sources) + 1

    def assemble(src):
        return _run([vasm, *flags, "-L", str(lst_dir / f"{src.stem}.lst"), "-o", str(obj_dir / f"{src.stem}.o"),
                     str(src)], cwd=str(src_root), timeout=120)

    # One vasm per file, several at once (1.5): each file is assembled on its own, so the
    # objects are the same; the link keeps the sorted order and the log the source order.
    from concurrent.futures import ThreadPoolExecutor
    done = 0
    with ThreadPoolExecutor(max_workers=max(1, min(8, os.cpu_count() or 1))) as pool:
        futures = [pool.submit(assemble, src) for src in sources]
        for src, fut in zip(sources, futures):
            rc, out = fut.result()
            done += 1
            progress(done * 100 // steps, f"Assembled {src.name} ({done}/{len(sources)})")
            if rc != 0:
                for line in out.strip().splitlines()[-30:]:
                    log(line)
                for f in futures:
                    f.cancel()
                raise BuildError(f"Assembly error in {src.name} (see the log).")
            log(f"[asm] {src.name}")
    progress((steps - 1) * 100 // steps, "Linking (vlink)")
    out_bin = BUILD_DIR / f"{TARGET_NAME}.bin"
    rc, out = _run([vlink, "-brawbin1", "-T", str(ld), "-o", str(out_bin), *objs], cwd=str(src_root), timeout=120)
    if rc != 0 or not out_bin.is_file():
        for line in out.strip().splitlines()[-30:]:
            log(line)
        raise BuildError("Link error (see the log).")
    log(f"[link] {out_bin.name} ({out_bin.stat().st_size} bytes)")
    progress(100, "Build finished")
    return out_bin


def check_briconeo(data):
    """Brico16Bits compatibility check. Returns [(ok, text)]."""
    res = []
    res.append((len(data) <= SP1_SIZE, f"Code size {len(data)} bytes (Brico16Bits maximum: {SP1_SIZE})"))
    if len(data) < OFF_TABLE + 8:
        res.append((False, "File too short to hold the BricoNeo header"))
        return res
    if int.from_bytes(data[0x8C:0x8E], "big") & 4:
        free = 0x7FFA - len(data)
        res.append((free >= 0, f"NeoDiag layout (header flag $0004): code ends before $7FFA, {free} bytes free "
                               "for new code"))
    reset_hi = struct.unpack_from(">H", data, 4)[0]
    pc = struct.unpack_from(">I", data, 4)[0]
    res.append((reset_hi == 0x00C0, f"Reset vector ${pc:08X}: byte order recognised by Brico16Bits "
                                    f"(upper word $00C0)"))
    magic = data[OFF_MAGIC:OFF_MAGIC + 8]
    res.append((magic == b"BricoNeo", f"Magic word at $80: {magic!r}"))
    major, minor = struct.unpack_from(">HH", data, OFF_VERSION)
    res.append((True, f"Announced version: {major}.{minor}"))
    flags = struct.unpack_from(">H", data, OFF_FLAGS)[0]
    res.append((bool(flags & FLAG_ENABLE_EXTENSIONS), f"Flags ${flags:04X} (extensions enabled: bit 0)"))
    res.append((struct.unpack_from(">H", data, OFF_JMP)[0] == 0x4EF9, "jmp opcode at $8E (BricoExt header)"))
    off, n, bad = OFF_TABLE, 0, []
    try:
        while True:
            addr, typ = struct.unpack_from(">IH", data, off)
            if addr == 0xFFFFFFFF:
                break
            off += 6
            end = data.index(b"\0", off); name = data[off:end].decode("latin-1"); off = end + 1 + ((end + 1) & 1)
            end = data.index(b"\0", off); desc = data[off:end]; off = end + 1 + ((end + 1) & 1)
            n += 1
            if not (0xC00000 <= addr < 0xC20000) or addr & 1:
                bad.append(f"{name}: address ${addr:06X} outside the ROM or odd")
            if typ > 3:
                bad.append(f"{name}: unknown result type {typ}")
            if not name or len(name) > HOST_NAME_MAX:
                bad.append(f"{name}: name empty or longer than {HOST_NAME_MAX} characters")
            if len(desc) >= HOST_DESC_MAX:
                bad.append(f"{name}: description longer than {HOST_DESC_MAX - 1} characters (truncated by the host)")
            if n > 200 or off >= len(data):
                raise ValueError("endless table")
        res.append((not bad, f"Extension table: {n} extension(s)" + (" - " + "; ".join(bad) if bad else "")))
    except Exception as e:
        res.append((False, f"Extension table unreadable: {e}"))
    return res


def make_sp1_image(data, fill=0xFF):
    """128 KB BricoNeo image. With header flag $0004 (bytes $8C-$8D), the image
    the BricoNeo builds itself on a mass-storage / serial load (Brico16Bits
    NeoDiagImageBuilder, same as tools/neodiag_image.py): CRC-32 of $0000-$7FFA
    at $7FFC ([B2 B3 B0 B1]), mirror number in $7FFA, copies at $8000, $10000,
    $18000 - so SendROMPart, MAME and the emulator see the same bytes.
    Otherwise: plain padding."""
    flags = int.from_bytes(data[0x8C:0x8E], "big") if len(data) >= 0x8E else 0
    if not (flags & 4) or len(data) > 0x7FFA:
        return data + bytes([fill]) * (SP1_SIZE - len(data))
    import zlib
    base = bytearray(data + bytes(0x8000 - len(data)))
    crc = zlib.crc32(bytes(base[:0x7FFB]))
    base[0x7FFC:0x8000] = bytes(((crc >> 16) & 0xFF, crc >> 24, crc & 0xFF, (crc >> 8) & 0xFF))
    out = bytearray(base)
    for m in (1, 2, 3):
        copy = bytearray(base)
        copy[0x7FFA] = m
        copy[0x7FFC:0x8000] = bytes(4)
        out += copy
    return bytes(out)

def find_briconeo_drives():
    """Drives that look like the BricoNeo USB drive (BANK0.. folders)."""
    cands = []
    if IS_WIN:
        roots = [Path(f"{c}:\\") for c in "DEFGHIJKLMNOPQRSTUVWXYZ"]
    else:
        roots = []
        for base in ("/media", "/run/media", "/Volumes", "/mnt"):
            b = Path(base)
            if b.is_dir():
                for p in b.glob("*"):
                    roots.append(p)
                    roots.extend(p.glob("*"))
    for r in roots:
        try:
            if (r / "BANK0").is_dir():
                cands.append(str(r))
        except OSError:
            pass
    return cands


# ---------------------------------------------------------------------------
# Source from GitHub
# ---------------------------------------------------------------------------
def _version_key(tag):
    return tuple(int(x) for x in re.findall(r"\d+", tag)) or (0,)


def latest_github_release(repo, log):
    """Tag of the latest release (GitHub API), else highest vX.Y tag (git), else None."""
    m = re.search(r"github\.com[/:]([^/]+)/([^/.]+)", repo)
    if m:
        try:
            import urllib.request
            req = urllib.request.Request(f"https://api.github.com/repos/{m.group(1)}/{m.group(2)}/releases/latest",
                                         headers={"User-Agent": f"{APP_NAME}/{APP_VERSION}",
                                                  "Accept": "application/vnd.github+json"})
            with urllib.request.urlopen(req, timeout=15) as r:
                tag = json.loads(r.read().decode("utf-8")).get("tag_name")
            if tag:
                log(f"Latest GitHub release: {tag}")
                return tag
        except Exception as e:
            log(f"GitHub API unavailable ({e}): looking for tags with git...")
    if shutil.which("git"):
        rc, out = _run(["git", "ls-remote", "--tags", repo], timeout=60)
        tags = [t for t in re.findall(r"refs/tags/([^\s^]+)$", out, re.M) if re.match(r"v?\d", t)]
        if rc == 0 and tags:
            tag = max(tags, key=_version_key)
            log(f"Latest GitHub tag (git): {tag}")
            return tag
    log(f"No release found: using branch {GITHUB_DEFAULT_BRANCH}.")
    return None


def fetch_github_source(repo, ref, dest, log, progress):
    """Downloads the source (empty ref = latest release) into dest. Returns (root, version)."""
    ref = (ref or "").strip() or latest_github_release(repo, log)
    label = ref or GITHUB_DEFAULT_BRANCH
    dest = Path(dest)
    errors = []
    urls = ([f"{repo}/archive/refs/tags/{ref}.zip", f"{repo}/archive/refs/heads/{ref}.zip"] if ref
            else [f"{repo}/archive/refs/heads/{GITHUB_DEFAULT_BRANCH}.zip"])
    for url in urls:
        try:
            log(f"Downloading {url}")
            arch = dest / "github.zip"
            _download(url, arch, log, progress)
            with zipfile.ZipFile(arch) as z:
                z.extractall(dest / "gh")
            return find_source_root(dest / "gh"), label
        except Exception as e:
            errors.append(f"{url}: {e}")
            log(f"  failed ({e})")
    if shutil.which("git"):
        log(f"git clone of {repo} ({label})...")
        cmd = ["git", "clone", "--depth", "1"] + (["--branch", ref] if ref else []) + [repo, str(dest / "git")]
        rc, out = _run(cmd, timeout=600)
        if rc == 0:
            return find_source_root(dest / "git"), label
        errors.append(f"git clone: {out.strip()[:200]}")
    raise BuildError("Could not get the source from GitHub:\n  " + "\n  ".join(errors))


# ---------------------------------------------------------------------------
# Full pipeline (used by the window and by --cli)
# ---------------------------------------------------------------------------
def full_build(source_mode, source_path, auto, manual_vasm, manual_vlink, out_dir, sp1, log, progress):
    t0 = time.time()
    with tempfile.TemporaryDirectory(prefix="b68ksrc_") as tmp:
        if source_mode == "zip":
            zp = Path(source_path)
            if not zp.is_file():
                raise BuildError(f"Archive not found: {zp}")
            log(f"Extracting {zp.name}...")
            progress(None, "Extracting the archive...")
            try:
                with zipfile.ZipFile(zp) as z:
                    z.extractall(tmp)
            except zipfile.BadZipFile as e:
                raise BuildError(f"Invalid zip archive: {e}")
            src_root = find_source_root(tmp)
        elif source_mode == "github":
            progress(None, "Getting the source from GitHub...")
            src_root, ver = fetch_github_source(GITHUB_REPO, source_path, tmp, log, progress)
            log(f"GitHub source: {GITHUB_REPO} ({ver}) - original version, WITHOUT the review fixes.")
        else:
            src_root = find_source_root(source_path)
        log(f"Source: {src_root} ({describe_source(src_root)})")
        vasm, vlink = resolve_tools(auto, manual_vasm, manual_vlink, log, progress)
        log(f"vasm: {vasm}")
        log(f"vlink: {vlink}")
        built = build_firmware(src_root, vasm, vlink, log, progress)
        data = built.read_bytes()
        fork = fork_version(src_root)
    checks = check_briconeo(data)
    final = make_sp1_image(data) if sp1 else data
    # The fork version (FORK_VERSION in inc/define.inc, e.g. "1.35-nic034-12") is not in the image
    # since 1.35-nic034-10: read from the source, the header must announce its base (1.35).
    fv = re.match(r"(\d+)\.(\d+)-[A-Za-z0-9]+-(\d+)$", fork or "")
    if fv:
        log("Fork version: " + fork)
        major, minor = struct.unpack_from(">HH", data, OFF_VERSION)
        want = (int(fv.group(1)), int(fv.group(2)))
        checks.append(((major, minor) == want, f"Header version {major}.{minor} = base of the fork version "
                       f"{fork}"))
    if sp1 and len(final) == SP1_SIZE and final[0x8D] & 4:
        checks.append((len(data) <= 0x7FFA, "NeoDiag layout (flag $0004): code fits below $7FFA, CRC32 + 3 mirrors"))
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    out_file = out_dir / ROM_FILE
    out_file.write_bytes(final)
    info = {
        "file": str(out_file),
        "code_size": len(data),
        "file_size": len(final),
        "sha256": hashlib.sha256(final).hexdigest(),
        "checks": checks,
        "ok": all(ok for ok, _ in checks),
        "seconds": time.time() - t0,
    }
    log(f"File: {out_file} ({len(final)} bytes, code {len(data)} bytes)")
    log(f"SHA-256: {info['sha256']}")
    for ok, txt in checks:
        log(("  [OK]   " if ok else "  [FAIL] ") + txt)
    return info


def fork_version(src_root):
    """FORK_VERSION of a nic034 fork source (macro in inc/define.inc), or None (upstream source)."""
    try:
        text = (Path(src_root) / "inc" / "define.inc").read_text(errors="replace")
    except OSError:
        return None
    m = re.search(r'macro\s+FORK_VERSION\s*\n\s*dc\.b\s+"([^"]+)"', text, re.I)
    return m.group(1) if m else None


# ---------------------------------------------------------------------------
# Text mode
# ---------------------------------------------------------------------------
def _parse_source(src):
    mode = "zip" if src.lower().endswith(".zip") else "folder"
    if src.lower().startswith("github"):
        mode, src = "github", src.partition(":")[2]
    return mode, src


def main_cli(argv):
    import argparse
    ap = argparse.ArgumentParser(description=APP_NAME)
    ap.add_argument("--cli", action="store_true")
    ap.add_argument("--check", action="store_true", help="only list missing files, do not build")
    ap.add_argument("--source", default=None, help="folder, .zip, or github[:tag] (default: the tool's folder)")
    ap.add_argument("--out", default=str(DEFAULT_OUT))
    ap.add_argument("--vasm"); ap.add_argument("--vlink")
    ap.add_argument("--code-only", action="store_true", help="do not pad to 128 KB")
    a = ap.parse_args(argv)
    src = a.source or default_source_dir()
    mode, src = _parse_source(src) if src else ("folder", "")
    if mode != "github" and src:
        src = str(Path(src).resolve())     # relative folder: vasm runs from another directory
    missing = startup_check(mode, src, a.out, (a.vasm, a.vlink))
    for what, detail in missing:
        print(f"MISSING: {what} -> {detail}")
    if a.check:
        print("OK: nothing missing" if not missing else f"{len(missing)} missing item(s)")
        return 1 if missing else 0
    if mode != "github" and not src:  # github with no tag = latest release
        print("Set --source (folder, .zip or github[:tag])"); return 2

    def progress(p, t):
        pass
    try:
        info = full_build(mode, src, True, a.vasm, a.vlink, a.out, not a.code_only, print, progress)
    except BuildError as e:
        print(f"ERROR: {e}"); return 1
    return 0 if info["ok"] else 3


# ---------------------------------------------------------------------------
# Window
# ---------------------------------------------------------------------------
def main_gui():
    import tkinter as tk
    from tkinter import filedialog, messagebox, ttk

    cfg = load_config()
    root = tk.Tk()
    root.title(f"{APP_NAME} {APP_VERSION}")
    root.minsize(760, 600)
    root.geometry("900x860")
    q = queue.Queue()
    state = {"busy": False, "last": None}
    pad = {"padx": 8, "pady": 4}

    def post(fn):
        q.put(fn)

    def drain():
        try:
            while True:
                q.get_nowait()()
        except queue.Empty:
            pass
        root.after(50, drain)

    # --- Missing files (red box, hidden when everything is there) ----------
    missing_var = tk.StringVar(value="")
    missing_box = tk.Label(root, textvariable=missing_var, justify="left", anchor="w", wraplength=860,
                           bg="#fdecea", fg="#7a1c14", bd=1, relief="solid", padx=10, pady=6)

    # --- 1. Source ---------------------------------------------------------
    f1 = ttk.LabelFrame(root, text="1. Brico68k firmware source")
    f1.pack(fill="x", **pad)
    src_mode = tk.StringVar(value=cfg.get("source_mode", "folder"))
    src_folder = tk.StringVar(value=cfg.get("source_folder") or default_source_dir())
    src_zip = tk.StringVar(value=cfg.get("source_zip", ""))
    src_info = tk.StringVar()

    r = ttk.Frame(f1); r.pack(fill="x", **pad)
    ttk.Radiobutton(r, text="Folder", variable=src_mode, value="folder", command=lambda: refresh_source()).pack(side="left")
    e_folder = ttk.Entry(r, textvariable=src_folder); e_folder.pack(side="left", fill="x", expand=True, padx=6)
    b_folder = ttk.Button(r, text="Browse...", command=lambda: pick_folder()); b_folder.pack(side="left")
    r = ttk.Frame(f1); r.pack(fill="x", **pad)
    ttk.Radiobutton(r, text=".zip archive", variable=src_mode, value="zip", command=lambda: refresh_source()).pack(side="left")
    e_zip = ttk.Entry(r, textvariable=src_zip); e_zip.pack(side="left", fill="x", expand=True, padx=6)
    b_zip = ttk.Button(r, text="Browse...", command=lambda: pick_zip()); b_zip.pack(side="left")
    REF_LATEST, REF_MAIN = "latest release", "main (development)"
    # French settings saved by 1.0/1.1 stay valid
    legacy_ref = {"dernière release": REF_LATEST, "main (développement)": REF_MAIN}
    src_ref = tk.StringVar(value=legacy_ref.get(cfg.get("source_ref"), cfg.get("source_ref")) or REF_LATEST)
    r = ttk.Frame(f1); r.pack(fill="x", **pad)
    ttk.Radiobutton(r, text="GitHub Aurelien34/Brico68k (downloaded automatically):",
                    variable=src_mode, value="github", command=lambda: refresh_source()).pack(side="left")
    e_ref = ttk.Combobox(r, textvariable=src_ref, values=[REF_LATEST, REF_MAIN], width=22)
    e_ref.pack(side="left", padx=6)
    e_ref.bind("<<ComboboxSelected>>", lambda _e: refresh_source())
    ttk.Label(r, text="(or a tag, e.g. v1.34)", foreground="#777").pack(side="left")
    lbl_src_info = ttk.Label(f1, textvariable=src_info, foreground="#555", wraplength=840, justify="left")
    lbl_src_info.pack(anchor="w", padx=8, pady=(0, 6))

    def pick_folder():
        d = filedialog.askdirectory(title="Brico68k source folder", initialdir=src_folder.get() or str(TOOL_DIR))
        if d:
            src_folder.set(d); refresh_source()

    def pick_zip():
        p = filedialog.askopenfilename(title="Brico68k source archive", filetypes=[("Zip archive", "*.zip"), ("All files", "*")])
        if p:
            src_zip.set(p); refresh_source()

    def refresh_source():
        mode = src_mode.get()
        folder = mode == "folder"
        e_folder.configure(state="normal" if folder else "disabled")
        b_folder.configure(state="normal" if folder else "disabled")
        e_zip.configure(state="normal" if mode == "zip" else "disabled")
        b_zip.configure(state="normal" if mode == "zip" else "disabled")
        e_ref.configure(state="normal" if mode == "github" else "disabled")
        lbl_src_info.configure(foreground="#b35c00" if mode == "github" else "#555")
        if mode == "github":
            src_info.set("Note: GitHub = Aurelien's original version, WITHOUT the review fixes (exception handlers, "
                         "RAM/palette tests, TestAudio, palette bank order...). 'main' is newer than the latest "
                         "release. For the reviewed version, use the 'source' folder delivered with this tool.")
        elif folder:
            try:
                rr = find_source_root(src_folder.get())
                src_info.set(f"OK: {describe_source(rr)}")
            except Exception as ex:
                src_info.set(f"! {ex}" if src_folder.get() else "Choose the folder that contains Brico68k.s")
        elif mode == "zip":
            p = src_zip.get()
            src_info.set("Archive selected (content checked when building)" if p and Path(p).is_file()
                         else "Choose the source .zip archive")
        refresh_missing()

    # --- 2. vasm / vlink ---------------------------------------------------
    f2 = ttk.LabelFrame(root, text="2. vasm assembler / vlink linker")
    f2.pack(fill="x", **pad)
    auto = tk.BooleanVar(value=cfg.get("auto", True))
    vasm_var = tk.StringVar(value=cfg.get("vasm", ""))
    vlink_var = tk.StringVar(value=cfg.get("vlink", ""))
    tool_info = tk.StringVar()
    ttk.Checkbutton(f2, text="Automatic (recommended): nothing to install, nothing to download", variable=auto,
                    command=lambda: refresh_tools()).pack(anchor="w", **pad)
    ttk.Label(f2, textvariable=tool_info, foreground="#555", wraplength=720, justify="left").pack(anchor="w", padx=8)
    manual = ttk.Frame(f2); manual.pack(fill="x", **pad)
    ttk.Label(manual, text="Or my own executables:", foreground="#555").grid(row=0, column=0, columnspan=3, sticky="w")
    for i, (lbl, var) in enumerate((("vasm:", vasm_var), ("vlink:", vlink_var)), start=1):
        ttk.Label(manual, text=lbl, width=7).grid(row=i, column=0, sticky="w")
        ttk.Entry(manual, textvariable=var).grid(row=i, column=1, sticky="we", padx=6, pady=2)
        ttk.Button(manual, text="Browse...", command=lambda v=var: pick_exe(v)).grid(row=i, column=2)
    manual.columnconfigure(1, weight=1)
    b_tools = ttk.Button(f2, text="Check / install now", command=lambda: start("tools"))
    b_tools.pack(anchor="w", **pad)

    def pick_exe(var):
        p = filedialog.askopenfilename(title="Executable", filetypes=[("Executable", "*.exe" if IS_WIN else "*"), ("All files", "*")])
        if p:
            var.set(p); refresh_tools()

    def refresh_tools():
        v, l = vasm_var.get().strip(), vlink_var.get().strip()
        if v and l:
            tool_info.set(f"Paths set: {v} / {l}")
        elif auto.get() and embedded_platform() in globals().get("EMBEDDED_TOOLS", {}):
            tool_info.set("vasm 1.9d and vlink 0.17a are embedded in the tool: they install themselves "
                          "on the first click on Build (no download).")
        else:
            fv, fl = locate_tools()
            if fv and fl:
                where = "in the tool's folder" if str(BIN_DIR) in str(fv) else f"in {Path(fv).parent}"
                tool_info.set(f"Ready: {Path(fv).name} and {Path(fl).name} ({where})")
            elif auto.get():
                tool_info.set("Not installed: they will be downloaded and built automatically on the first build "
                              f"(once, in {TOOLCHAIN_DIR}).")
            else:
                tool_info.set("Not installed: set both executables below, or tick Automatic.")
        refresh_missing()

    # --- 3. Build ----------------------------------------------------------
    f3 = ttk.LabelFrame(root, text="3. Build")
    f3.pack(fill="x", **pad)
    sp1 = tk.BooleanVar(value=cfg.get("sp1", True))
    out_dir = tk.StringVar(value=cfg.get("out_dir", str(DEFAULT_OUT)))
    ttk.Checkbutton(f3, text="Full 128 KB image (SP1 ROM size, padded with $FF) - recommended for the BricoNeo",
                    variable=sp1).pack(anchor="w", **pad)
    r = ttk.Frame(f3); r.pack(fill="x", **pad)
    ttk.Label(r, text="Output folder:").pack(side="left")
    ttk.Entry(r, textvariable=out_dir).pack(side="left", fill="x", expand=True, padx=6)
    ttk.Button(r, text="Browse...", command=lambda: (lambda d: d and out_dir.set(d))(
        filedialog.askdirectory(title="Output folder", initialdir=out_dir.get()))).pack(side="left")
    r = ttk.Frame(f3); r.pack(fill="x", **pad)
    b_build = ttk.Button(r, text="Build", command=lambda: start("build"))
    b_build.pack(side="left")
    b_open = ttk.Button(r, text="Open output folder", command=lambda: open_folder(out_dir.get()))
    b_open.pack(side="left", padx=8)
    result = tk.StringVar(value="")
    lbl_result = ttk.Label(f3, textvariable=result, justify="left", wraplength=720)
    lbl_result.pack(anchor="w", padx=8, pady=(0, 6))

    def open_folder(p):
        p = Path(p)
        if not p.is_dir():
            return
        try:
            if IS_WIN:
                os.startfile(str(p))  # noqa
            elif sys.platform == "darwin":
                subprocess.Popen(["open", str(p)])
            else:
                subprocess.Popen(["xdg-open", str(p)])
        except Exception:
            pass

    # --- 4. Send to the BricoNeo ------------------------------------------
    f4 = ttk.LabelFrame(root, text="4. Send to the BricoNeo ('BricoNeo' USB drive)")
    f4.pack(fill="x", **pad)
    drive = tk.StringVar(value=cfg.get("drive", ""))
    dest_choices = ["BANK0 - saved, loaded at start-up", "BANK1 - saved", "BANK2 - saved",
                    "BANK3 - saved", "Root - loaded into RAM only (lost at power-off)"]
    saved_key = cfg.get("dest", "").split(" ")[0]  # "BANK0".."BANK3", "Root" (or "Racine" from 1.0/1.1)
    dest = tk.StringVar(value=dest_choices[4] if saved_key in ("Root", "Racine")
                        else next((c for c in dest_choices if c.split(" ")[0] == saved_key), dest_choices[0]))
    r = ttk.Frame(f4); r.pack(fill="x", **pad)
    ttk.Label(r, text="Drive:").pack(side="left")
    ttk.Entry(r, textvariable=drive, width=28).pack(side="left", padx=6)
    ttk.Button(r, text="Detect", command=lambda: detect_drive()).pack(side="left")
    ttk.Button(r, text="Browse...", command=lambda: (lambda d: d and drive.set(d))(
        filedialog.askdirectory(title="BricoNeo USB drive"))).pack(side="left", padx=6)
    r = ttk.Frame(f4); r.pack(fill="x", **pad)
    ttk.Label(r, text="Destination:").pack(side="left")
    ttk.Combobox(r, textvariable=dest, values=dest_choices, state="readonly", width=52).pack(side="left", padx=6)
    b_send = ttk.Button(r, text="Copy ROM.BIO", command=lambda: send())
    b_send.pack(side="left")

    def detect_drive():
        c = find_briconeo_drives()
        if c:
            drive.set(c[0]); status.set(f"BricoNeo drive detected: {c[0]}")
        else:
            messagebox.showinfo(APP_NAME, "No BricoNeo drive detected (drive with a BANK0 folder).\n"
                                          "Plug the BricoNeo in over USB, or choose the drive with 'Browse'.")

    def send():
        src = Path(out_dir.get()) / ROM_FILE
        if not src.is_file():
            messagebox.showerror(APP_NAME, f"Build first: {ROM_FILE} not found in the output folder.")
            return
        d = drive.get().strip()
        if not d or not Path(d).is_dir():
            messagebox.showerror(APP_NAME, "Choose the BricoNeo USB drive (Detect or Browse button).")
            return
        target_dir = Path(d) if dest.get().startswith("Root") else Path(d) / dest.get().split(" ")[0]
        if not target_dir.is_dir():
            messagebox.showerror(APP_NAME, f"{target_dir} does not exist: is this really the BricoNeo drive?")
            return
        try:
            shutil.copyfile(src, target_dir / ROM_FILE)
        except OSError as ex:
            messagebox.showerror(APP_NAME, f"Copy failed: {ex}")
            return
        persist()
        log(f"Copied to the BricoNeo: {target_dir / ROM_FILE}")
        messagebox.showinfo(APP_NAME, f"Copied to {target_dir}.\nThe BricoNeo programs the file then "
                                      "reconnects (the file disappears from the drive: this is normal).")

    # --- Progress + log ----------------------------------------------------
    fp = ttk.Frame(root); fp.pack(fill="x", **pad)
    prog_text = tk.StringVar(value="")
    ttk.Label(fp, textvariable=prog_text, foreground="#555").pack(anchor="w")
    bar = ttk.Progressbar(fp, mode="determinate", maximum=100)
    bar.pack(fill="x")
    status = tk.StringVar(value="Ready.")
    ttk.Label(root, textvariable=status, anchor="w", relief="sunken").pack(fill="x", side="bottom")
    fl = ttk.LabelFrame(root, text="Log")
    fl.pack(fill="both", expand=True, **pad)
    logbox = tk.Text(fl, height=7, wrap="word", state="disabled", font=("Consolas", 9) if IS_WIN else ("Monospace", 9))
    sb = ttk.Scrollbar(fl, command=logbox.yview)
    logbox.configure(yscrollcommand=sb.set)
    sb.pack(side="right", fill="y"); logbox.pack(fill="both", expand=True)

    def log(msg):
        def _do():
            logbox.configure(state="normal")
            logbox.insert("end", msg + "\n")
            logbox.see("end")
            logbox.configure(state="disabled")
        post(_do)

    def progress(pct, text):
        def _do():
            if pct is None:
                if str(bar.cget("mode")) != "indeterminate":
                    bar.configure(mode="indeterminate"); bar.start(12)
            else:
                if str(bar.cget("mode")) != "determinate":
                    bar.stop(); bar.configure(mode="determinate")
                bar["value"] = pct
            prog_text.set(text)
        post(_do)

    last_missing = {"text": None}

    def refresh_missing():
        """Shows the red box listing what the next build is missing (hidden when complete)."""
        mode = src_mode.get()
        path = {"folder": src_folder.get().strip(), "zip": src_zip.get().strip()}.get(mode, "")
        man = (vasm_var.get().strip(), vlink_var.get().strip()) if not auto.get() else None
        try:
            items = startup_check(mode, path, out_dir.get().strip(), man)
        except Exception as ex:  # never let the check itself break the window
            items = [("start-up check failed", repr(ex))]
        if items:
            text = f"Missing ({len(items)}) - fix before building:\n" + "\n".join(f"  • {w}: {d}" for w, d in items)
            missing_var.set(text)
            if not missing_box.winfo_ismapped():
                missing_box.pack(fill="x", padx=8, pady=(8, 0), before=f1)
            if text != last_missing["text"]:
                for w, d in items:
                    log(f"MISSING: {w} -> {d}")
        else:
            missing_box.pack_forget()
        last_missing["text"] = missing_var.get() if items else None
        return not items

    def persist():
        save_config({"source_mode": src_mode.get(), "source_folder": src_folder.get(), "source_zip": src_zip.get(),
                     "source_ref": src_ref.get(),
                     "auto": auto.get(), "vasm": vasm_var.get(), "vlink": vlink_var.get(), "sp1": sp1.get(),
                     "out_dir": out_dir.get(), "drive": drive.get(), "dest": dest.get()})

    buttons = [b_build, b_tools, b_send, b_folder, b_zip]

    def set_busy(b):
        state["busy"] = b
        for w in buttons:
            w.configure(state="disabled" if b else "normal")
        if not b:
            refresh_source()

    def done(ok_text, err=None):
        bar.stop(); bar.configure(mode="determinate")
        bar["value"] = 100 if err is None else 0
        prog_text.set(ok_text if err is None else "Failed")
        status.set(ok_text if err is None else f"Failed: {err}")
        set_busy(False)
        refresh_tools()

    def start(what):
        if state["busy"]:
            return
        if what == "build" and not refresh_missing():
            status.set("Cannot build: some files are missing (see the red box).")
            return
        persist()
        set_busy(True)
        result.set("")
        ref = src_ref.get().strip()
        ref = "" if ref in ("", REF_LATEST) else ("main" if ref == REF_MAIN else ref)
        args = (src_mode.get(), {"folder": src_folder.get(), "zip": src_zip.get()}.get(src_mode.get(), ref), auto.get(),
                vasm_var.get().strip() or None, vlink_var.get().strip() or None, out_dir.get(), sp1.get())

        def worker():
            try:
                if what == "tools":
                    progress(None, "Checking vasm/vlink...")
                    v, l = resolve_tools(args[2], args[3], args[4], log, progress)
                    log(f"OK - vasm: {v}")
                    log(f"OK - vlink: {l}")
                    post(lambda: done("vasm and vlink are ready."))
                else:
                    log("=" * 60)
                    info = full_build(*args, log, progress)
                    state["last"] = info
                    n_ok = sum(1 for ok, _ in info["checks"] if ok)
                    failed = [t for ok, t in info["checks"] if not ok]
                    verdict = (f"COMPATIBLE with BricoNeo / Brico16Bits: {n_ok}/{len(info['checks'])} checks OK "
                               "(details in the log)" if info["ok"]
                               else "WARNING - compatibility check failed:\n  " + "\n  ".join(failed))
                    txt = (f"{verdict}\n{Path(info['file']).name}: {info['file_size']} bytes "
                           f"(code {info['code_size']} bytes) - SHA-256 {info['sha256'][:16]}...")
                    post(lambda: (result.set(txt), lbl_result.configure(foreground="#1a7f37" if info["ok"] else "#b00020"),
                                  done(f"Build succeeded in {info['seconds']:.1f} s")))
            except BuildError as ex:
                msg = str(ex)
                log(f"ERROR: {msg}")
                post(lambda: (done("", msg), messagebox.showerror(APP_NAME, msg)))
            except Exception as ex:  # noqa - show everything rather than die silently
                msg = f"Unexpected error: {ex!r}"
                log(msg)
                post(lambda: (done("", msg), messagebox.showerror(APP_NAME, msg)))

        threading.Thread(target=worker, daemon=True).start()

    def on_close():
        persist()
        root.destroy()

    for var in (src_folder, src_zip, out_dir, vasm_var, vlink_var):
        var.trace_add("write", lambda *_: refresh_missing())
    root.protocol("WM_DELETE_WINDOW", on_close)
    log(f"{APP_NAME} {APP_VERSION} - Python {sys.version.split()[0]} - work folder: {WORK_DIR}")
    refresh_source()
    refresh_tools()
    if not missing_box.winfo_ismapped():
        log("Start-up check: nothing missing.")
    root.after(50, drain)
    root._b68k = {"start": start, "src_mode": src_mode, "src_folder": src_folder, "src_zip": src_zip, "auto": auto,
                  "src_ref": src_ref, "src_info": src_info, "tool_info": tool_info,
                  "vasm": vasm_var, "vlink": vlink_var, "out_dir": out_dir, "sp1": sp1, "state": state,
                  "result": result, "status": status, "send": send, "drive": drive, "dest": dest,
                  "dest_choices": dest_choices, "detect": detect_drive,
                  "missing": missing_var, "missing_box": missing_box}  # access for automated tests
    return root


